  const [ranking, setRanking] = useState<RankingEntry[]>([]);
  const [recentInvoices, setRecentInvoices] = useState<Invoice[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    setLoading(true);
    // Find the commercial linked to this user
    client.get('/commercials', { params: { per_page: 200 } })
      .then(({ data }) => {
        if (!active) return;
        const commercials: Commercial[] = data.data ?? [];
        const mine = commercials.find((c) => c.user_id === user?.id);
        if (!mine) return;
        setCommercial(mine);
        return Promise.all([
          commercialsApi.stats(mine.id),
          commercialsApi.ranking(),
          invoicesApi.list({ commercial_id: mine.id, per_page: 5 }),
        ]);
      })
      .then((results) => {
        if (!active || !results) return;
        const [s, r, inv] = results;
        setStats(s);
        setRanking(r);
        setRecentInvoices(inv.invoices.data ?? []);
      })
      .catch(() => {})
      .finally(() => {
        if (active) setLoading(false);
