import type { useTranslation } from 'react-i18next';
import type { LucideIcon } from 'lucide-react';
import {
  Briefcase,
  Building2,
  Contact,
  FileText,
  FolderTree,
  History,
  LayoutDashboard,
  Package,
  Settings,
  Shield,
  Users,
} from 'lucide-react';

export const ADMIN_ROLES = ['super-admin', 'direction-generale'];

type TranslateFn = ReturnType<typeof useTranslation>['t'];

export interface NavItem {
  to: string;
  label: string;
  icon: LucideIcon;
  end: boolean;
}

function catalogItem(t: TranslateFn): NavItem {
  return { to: '/catalog', label: t('nav.catalog'), icon: Package, end: false };
}

export function getMainItems(t: TranslateFn, roleName: string | null | undefined, agencyId?: string): NavItem[] {
  const baseItems: NavItem[] = [
    { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
    { to: '/clients', label: t('nav.clients'), icon: Contact, end: false },
  ];

  const commercialItems: NavItem[] = [
    ...baseItems,
    { to: '/commercials', label: t('nav.commercials'), icon: Briefcase, end: false },
    { to: '/invoices', label: t('nav.invoices'), icon: FileText, end: false },
  ];

  if (ADMIN_ROLES.includes(roleName ?? '')) {
    return [
      ...baseItems,
      { to: '/agencies', label: t('nav.agencies'), icon: Building2, end: false },
      { to: '/users', label: t('nav.users'), icon: Users, end: false },
      { to: '/privileges', label: t('nav.privileges'), icon: Shield, end: false },
      catalogItem(t),
      { to: '/audit', label: t('nav.audit'), icon: History, end: false },
      { to: '/settings', label: t('nav.settings'), icon: Settings, end: false },
    ];
  }

  if (roleName === 'responsable-agence') {
    return [
      ...baseItems,
      { to: '/agencies', label: t('nav.myAgencies'), icon: Building2, end: false },
      { to: '/departments', label: t('nav.departments'), icon: FolderTree, end: false },
      ...(agencyId
        ? [{ to: `/users?agency_id=${agencyId}`, label: t('nav.myTeam'), icon: Users, end: false as const }]
        : []),
      catalogItem(t),
    ];
  }

  if (roleName === 'responsable-departement') {
    return [
      ...commercialItems,
      { to: '/departments', label: t('nav.myDepartments'), icon: FolderTree, end: false },
      { to: '/users', label: t('nav.myTeam'), icon: Users, end: false },
      catalogItem(t),
    ];
  }

  if (roleName === 'caissier') {
    return [
      { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
      { to: '/clients', label: t('nav.clients'), icon: Contact, end: false },
      { to: '/invoices', label: t('nav.invoices'), icon: FileText, end: false },
      catalogItem(t),
    ];
  }

  if (roleName === 'comptable') {
    return [
      { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
      { to: '/clients', label: t('nav.clients'), icon: Contact, end: false },
      { to: '/commercials', label: t('nav.commercials'), icon: Briefcase, end: false },
      { to: '/invoices', label: t('nav.invoices'), icon: FileText, end: false },
      catalogItem(t),
    ];
  }

  if (roleName === 'commercial') {
    return [
      ...commercialItems,
      catalogItem(t),
    ];
  }

  return [
    { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
    catalogItem(t),
  ];
}

export function navLinkClass({ isActive }: { isActive: boolean }) {
  return `flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors ${
    isActive
      ? 'bg-brand-50 text-brand-700 dark:bg-brand-500/10 dark:text-brand-300'
      : 'text-gray-600 hover:bg-gray-50 dark:text-gray-300 dark:hover:bg-gray-800'
  }`;
}

import { NavLink } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { UserRound } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { getMainItems, navLinkClass } from '@/components/layout/navItems';

export function Sidebar() {
  const { t } = useTranslation();
  const { user } = useAuth();
  const agencyAssignment = user?.assignments?.find((a: any) => a.pivot?.is_primary === true);
  const mainItems = getMainItems(t, user?.role?.name, agencyAssignment?.id);

  return (
    <aside className="hidden w-64 shrink-0 flex-col border-r border-gray-100 bg-white px-4 py-6 dark:border-gray-800 dark:bg-gray-900 lg:sticky lg:top-0 lg:flex lg:h-screen lg:overflow-y-auto">
      <div className="mb-8 px-2">
        <span className="text-xl font-semibold tracking-tight text-brand-600 dark:text-brand-400">
          PEKEGNO
        </span>
      </div>
      <nav className="flex flex-1 flex-col gap-1">
        {mainItems.map(({ to, label, icon: Icon, end }) => (
          <NavLink key={to} to={to} end={end} className={navLinkClass}>
            <Icon className="h-5 w-5" />
            {label}
          </NavLink>
        ))}
      </nav>
      <nav className="border-t border-gray-100 pt-4 dark:border-gray-800">
        <NavLink to="/profile" end={false} className={navLinkClass}>
          <UserRound className="h-5 w-5" />
          {t('nav.myProfile')}
        </NavLink>
      </nav>
    </aside>
  );
}

import { Outlet } from 'react-router-dom';
import { Sidebar } from './Sidebar';
import { MobileNav } from './MobileNav';
import { UserMenu } from '@/components/common/UserMenu';

export function AppLayout() {
  return (
    <div className="flex min-h-screen bg-gray-50 dark:bg-gray-950">
      <Sidebar />
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="flex h-16 items-center justify-between border-b border-gray-100 bg-white px-4 dark:border-gray-800 dark:bg-gray-900 sm:px-6">
          <div className="mr-auto">
            <MobileNav />
          </div>
          <UserMenu />
        </header>
        <main className="flex-1 p-4 sm:p-6">
          <Outlet />
        </main>
      </div>
    </div>
  );
}

