import type { useTranslation } from 'react-i18next';
import type { LucideIcon } from 'lucide-react';
import {
  Briefcase,
  Building2,
  Contact,
  FileText,
  FolderTree,
  History,
  LayoutDashboard,
  Package,
  Settings,
  Shield,
  Users,
} from 'lucide-react';

export const ADMIN_ROLES = ['super-admin', 'direction-generale'];

type TranslateFn = ReturnType<typeof useTranslation>['t'];

export interface NavItem {
  to: string;
  label: string;
  icon: LucideIcon;
  end: boolean;
  badge?: number;
}

function catalogItem(t: TranslateFn): NavItem {
  return { to: '/catalog', label: t('nav.catalog'), icon: Package, end: false };
}

export const INVOICES_ROLES = new Set(['super-admin', 'direction-generale', 'responsable-departement', 'caissier', 'comptable', 'commercial']);

function invoiceItem(t: TranslateFn, badge?: number): NavItem {
  return { to: '/invoices', label: t('nav.invoices'), icon: FileText, end: false, badge };
}

export function getMainItems(t: TranslateFn, roleName: string | null | undefined, agencyId?: string, unpaidBadge?: number): NavItem[] {
  const baseItems: NavItem[] = [
    { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
    { to: '/clients', label: t('nav.clients'), icon: Contact, end: false },
  ];

  const commercialItems: NavItem[] = [
    ...baseItems,
    { to: '/commercials', label: t('nav.commercials'), icon: Briefcase, end: false },
    invoiceItem(t, unpaidBadge),
  ];

  if (ADMIN_ROLES.includes(roleName ?? '')) {
    return [
      ...baseItems,
      { to: '/agencies', label: t('nav.agencies'), icon: Building2, end: false },
      { to: '/users', label: t('nav.users'), icon: Users, end: false },
      { to: '/privileges', label: t('nav.privileges'), icon: Shield, end: false },
      catalogItem(t),
      { to: '/audit', label: t('nav.audit'), icon: History, end: false },
      { to: '/settings', label: t('nav.settings'), icon: Settings, end: false },
    ];
  }

  if (roleName === 'responsable-agence') {
    return [
      ...baseItems,
      { to: '/agencies', label: t('nav.myAgencies'), icon: Building2, end: false },
      { to: '/departments', label: t('nav.departments'), icon: FolderTree, end: false },
      ...(agencyId
        ? [{ to: `/users?agency_id=${agencyId}`, label: t('nav.myTeam'), icon: Users, end: false as const }]
        : []),
      catalogItem(t),
    ];
  }

  if (roleName === 'responsable-departement') {
    return [
      ...commercialItems,
      { to: '/departments', label: t('nav.myDepartments'), icon: FolderTree, end: false },
      { to: '/users', label: t('nav.myTeam'), icon: Users, end: false },
      catalogItem(t),
    ];
  }

  if (roleName === 'caissier') {
    return [
      { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
      { to: '/clients', label: t('nav.clients'), icon: Contact, end: false },
      invoiceItem(t, unpaidBadge),
      catalogItem(t),
    ];
  }

  if (roleName === 'comptable') {
    return [
      { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
      { to: '/clients', label: t('nav.clients'), icon: Contact, end: false },
      { to: '/commercials', label: t('nav.commercials'), icon: Briefcase, end: false },
      invoiceItem(t, unpaidBadge),
      catalogItem(t),
    ];
  }

  if (roleName === 'commercial') {
    return [
      ...commercialItems,
      catalogItem(t),
    ];
  }

  return [
    { to: '/', label: t('nav.dashboard'), icon: LayoutDashboard, end: true },
    catalogItem(t),
  ];
}

export function navLinkClass({ isActive }: { isActive: boolean }) {
  return `flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors ${
    isActive
      ? 'bg-brand-50 text-brand-700 dark:bg-brand-500/10 dark:text-brand-300'
      : 'text-gray-600 hover:bg-gray-50 dark:text-gray-300 dark:hover:bg-gray-800'
  }`;
}

import { useEffect, useState } from 'react';
import { NavLink } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { UserRound } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { getMainItems, navLinkClass, INVOICES_ROLES } from '@/components/layout/navItems';
import { invoicesApi } from '@/api/invoices.api';

export function Sidebar() {
  const { t } = useTranslation();
  const { user } = useAuth();
  const [unpaidBadge, setUnpaidBadge] = useState<number>(0);
  const agencyAssignment = user?.assignments?.find((a: any) => a.pivot?.is_primary === true);
  const roleName = user?.role?.name;

  useEffect(() => {
    if (!roleName || !INVOICES_ROLES.has(roleName)) return;
    let cancelled = false;
    invoicesApi.list({ status: 'unpaid', per_page: 1 }).then((res) => {
      if (!cancelled) setUnpaidBadge(res.invoices.meta.total);
    }).catch(() => {});
    return () => { cancelled = true; };
  }, [roleName]);

  const mainItems = getMainItems(t, roleName, agencyAssignment?.id, unpaidBadge);

  return (
    <aside className="hidden w-64 shrink-0 flex-col border-r border-gray-100 bg-white px-4 py-6 dark:border-gray-800 dark:bg-gray-900 lg:sticky lg:top-0 lg:flex lg:h-screen lg:overflow-y-auto">
      <div className="mb-8 px-2">
        <span className="text-xl font-semibold tracking-tight text-brand-600 dark:text-brand-400">
          PEKEGNO
        </span>
      </div>
      <nav className="flex flex-1 flex-col gap-1">
        {mainItems.map(({ to, label, icon: Icon, end, badge }) => (
          <NavLink key={to} to={to} end={end} className={navLinkClass}>
            <Icon className="h-5 w-5" />
            {label}
            {badge != null && badge > 0 && (
              <span
                className="ml-auto rounded-full bg-red-500 px-1.5 py-0.5 text-[10px] font-bold text-white"
                aria-label={t('nav.unpaidBadge', { count: badge })}
              >
                {badge > 99 ? '99+' : badge}
              </span>
            )}
          </NavLink>
        ))}
      </nav>
      <nav className="border-t border-gray-100 pt-4 dark:border-gray-800">
        <NavLink to="/profile" end={false} className={navLinkClass}>
          <UserRound className="h-5 w-5" />
          {t('nav.myProfile')}
        </NavLink>
      </nav>
    </aside>
  );
}

import { useEffect, useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { Menu, UserRound, X } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { getMainItems, navLinkClass, INVOICES_ROLES, type NavItem } from '@/components/layout/navItems';
import { invoicesApi } from '@/api/invoices.api';

interface MobileNavProps {
  contextTitle?: string;
  contextItems?: NavItem[];
  contextOnly?: boolean;
}

export function MobileNav({ contextTitle, contextItems = [], contextOnly = false }: MobileNavProps) {
  const { t } = useTranslation();
  const { user } = useAuth();
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);
  const [unpaidBadge, setUnpaidBadge] = useState<number>(0);
  const agencyAssignment = user?.assignments?.find((a: any) => a.pivot?.is_primary === true);
  const roleName = user?.role?.name;

  useEffect(() => {
    if (!roleName || !INVOICES_ROLES.has(roleName)) return;
    let cancelled = false;
    invoicesApi.list({ status: 'unpaid', per_page: 1 }).then((res) => {
      if (!cancelled) setUnpaidBadge(res.invoices.meta.total);
    }).catch(() => {});
    return () => { cancelled = true; };
  }, [roleName]);

  const mainItems = getMainItems(t, roleName, agencyAssignment?.id, unpaidBadge);
  const fullName =
    [user?.first_name, user?.last_name].filter(Boolean).join(' ') || user?.username || '—';

  useEffect(() => {
    setIsOpen(false);
  }, [location.pathname, location.search]);

  useEffect(() => {
    document.body.style.overflow = isOpen ? 'hidden' : '';
    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') setIsOpen(false);
    }
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  return (
    <>
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        className="rounded-lg p-2 text-gray-500 hover:bg-gray-100 hover:text-gray-700 lg:hidden dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-gray-100"
        aria-label={t('common.menu')}
      >
        <Menu className="h-5 w-5" />
      </button>

      {isOpen && (
        <div className="fixed inset-0 z-50 lg:hidden">
          <div
            className="absolute inset-0 bg-black/40"
            onClick={() => setIsOpen(false)}
            aria-hidden
          />
          <div className="absolute inset-y-0 left-0 flex w-72 max-w-[80vw] flex-col border-r border-gray-100 bg-white px-4 py-6 shadow-xl dark:border-gray-800 dark:bg-gray-900">
            <div className="mb-8 flex items-center justify-between px-2">
              <span className="text-xl font-semibold tracking-tight text-brand-600 dark:text-brand-400">
                PEKEGNO
              </span>
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="rounded-lg p-2 text-gray-500 hover:bg-gray-100 hover:text-gray-700 dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-gray-100"
                aria-label={t('common.close')}
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {contextOnly ? (
              <>
                {contextTitle && (
                  <p className="mb-2 px-2 text-xs font-semibold uppercase tracking-wider text-gray-400 dark:text-gray-500">
